create or replace function private.business_report(p_from date,p_to date) returns jsonb language plpgsql stable security definer set search_path='' as $$
declare lo timestamptz;hi timestamptz;sales numeric;cost numeric;returned_cost numeric;fees numeric;other_cost numeric;refunds numeric;receipts numeric;cash_refunds numeric;expenses numeric;unknown_costs int;unknown_refunds int;summary jsonb;daily jsonb;channels jsonb;popular jsonb;todo jsonb;
begin
 if not private.is_store_admin() then raise insufficient_privilege;end if;
 if p_from is null or p_to is null or p_to<p_from or p_to-p_from>366 then raise invalid_parameter_value using message='Choose a report period of at most 367 days';end if;
 lo:=p_from::timestamp at time zone 'Asia/Taipei';hi:=(p_to+1)::timestamp at time zone 'Asia/Taipei';
 select coalesce(sum(o.public_subtotal_twd::numeric+o.private_adjustments_twd),0),coalesce(sum(o.fee_twd),0),coalesce(sum(o.other_cost_twd),0) into sales,fees,other_cost from public.orders o where o.fulfilled_at>=lo and o.fulfilled_at<hi;
 select coalesce(sum(i.quantity*i.unit_cost_snapshot_twd),0),count(*) filter(where i.unit_cost_snapshot_twd is null) into cost,unknown_costs from public.order_items i join public.orders o on o.id=i.order_id where o.fulfilled_at>=lo and o.fulfilled_at<hi;
 select coalesce(sum(m.quantity_delta*c.cost),0) into returned_cost from public.inventory_movements m join lateral(select sum(i.quantity*i.unit_cost_snapshot_twd)/nullif(sum(i.quantity),0) cost from public.order_items i where i.order_id=m.related_order_id and i.product_id=m.product_id)c on true where m.movement_type='cancel_return' and m.created_at>=lo and m.created_at<hi;
 select coalesce(sum(p.amount_twd)filter(where p.kind='receipt'),0),coalesce(sum(p.amount_twd)filter(where p.kind='refund'),0),coalesce(sum(p.amount_twd)filter(where p.kind='refund' and p.affects_revenue),0),count(*)filter(where p.kind='refund' and p.affects_revenue is null) into receipts,cash_refunds,refunds,unknown_refunds from public.order_payments p where p.voided_at is null and p.occurred_at>=lo and p.occurred_at<hi;
 select coalesce(sum(e.amount_twd),0) into expenses from public.expenses e where e.voided_at is null and e.spent_at between p_from and p_to;
 summary:=jsonb_build_object('sales_twd',sales::text,'sales_refunds_twd',refunds::text,'net_sales_twd',(sales-refunds)::text,'cogs_twd',cost::text,'returned_cost_twd',returned_cost::text,'net_cogs_twd',(cost-returned_cost)::text,'fees_twd',fees::text,'other_cost_twd',other_cost::text,'expenses_twd',expenses::text,'estimated_profit_twd',case when unknown_costs+unknown_refunds=0 and not exists(select 1 from public.inventory_movements m join public.order_items i on i.order_id=m.related_order_id and i.product_id=m.product_id where m.movement_type='cancel_return'and m.created_at>=lo and m.created_at<hi and i.unit_cost_snapshot_twd is null) then (sales-refunds-cost+returned_cost-fees-other_cost-expenses)::text end,'receipts_twd',receipts::text,'cash_refunds_twd',cash_refunds::text,'net_receipts_twd',(receipts-cash_refunds)::text,'unknown_cost_rows',unknown_costs,'unclassified_refunds',unknown_refunds,
 'undated_payment_entries',(select count(*) from public.order_payments where voided_at is null and occurred_at is null),
 'outstanding_twd',(select coalesce(sum(greatest(o.public_subtotal_twd::bigint+o.private_adjustments_twd-o.received_amount_twd+o.refund_amount_twd,0)),0)::text from public.orders o where o.status not in ('cancelled','refunded','refund_pending')),
 'stock_value_twd',(select coalesce(sum(b.quantity_on_hand*v.unit_cost_twd),0)::text from public.inventory_balances b left join public.inventory_valuations v using(product_id)),
 'unknown_stock_products',(select count(*) from public.inventory_balances b left join public.inventory_valuations v using(product_id) where b.quantity_on_hand>0 and v.unit_cost_twd is null),
 'inventory_mismatches',(select count(*) from public.inventory_balances b where b.quantity_on_hand<>(select coalesce(sum(m.quantity_delta),0) from public.inventory_movements m where m.product_id=b.product_id)),
 'payment_mismatches',(select count(*) from public.orders o where o.received_amount_twd<>(select coalesce(sum(p.amount_twd),0) from public.order_payments p where p.order_id=o.id and p.kind='receipt' and p.voided_at is null) or o.refund_amount_twd<>(select coalesce(sum(p.amount_twd),0) from public.order_payments p where p.order_id=o.id and p.kind='refund' and p.voided_at is null)));
 select coalesce(jsonb_agg(jsonb_build_object('date',d.day::date,'sales_twd',(select coalesce(sum(o.public_subtotal_twd::numeric+o.private_adjustments_twd),0)::text from public.orders o where (o.fulfilled_at at time zone 'Asia/Taipei')::date=d.day::date),'receipts_twd',(select coalesce(sum(p.amount_twd),0)::text from public.order_payments p where p.voided_at is null and p.kind='receipt' and (p.occurred_at at time zone 'Asia/Taipei')::date=d.day::date),'refunds_twd',(select coalesce(sum(p.amount_twd),0)::text from public.order_payments p where p.voided_at is null and p.kind='refund' and (p.occurred_at at time zone 'Asia/Taipei')::date=d.day::date),'expenses_twd',(select coalesce(sum(e.amount_twd),0)::text from public.expenses e where e.voided_at is null and e.spent_at=d.day::date))order by d.day),'[]') into daily from generate_series(p_from::timestamp,p_to::timestamp,interval '1 day')d(day);
 select coalesce(jsonb_agg(jsonb_build_object('channel',c.channel,'orders',c.orders,'sales_twd',c.sales::text,'fees_twd',c.fees::text)order by c.sales desc),'[]') into channels from(select o.channel,count(*)orders,sum(o.public_subtotal_twd::numeric+o.private_adjustments_twd)sales,sum(o.fee_twd)fees from public.orders o where o.fulfilled_at>=lo and o.fulfilled_at<hi group by o.channel)c;
 select coalesce(jsonb_agg(to_jsonb(p)order by p.quantity desc),'[]') into popular from(select i.product_id,min(i.product_name_snapshot)name,sum(i.quantity)quantity,sum(i.quantity::numeric*i.sale_unit_price_twd)::text sales_twd from public.order_items i join public.orders o on o.id=i.order_id where o.fulfilled_at>=lo and o.fulfilled_at<hi group by i.product_id order by sum(i.quantity)desc limit 20)p;
 todo:=jsonb_build_object('pending_review',(select count(*)from public.orders where status='pending_review'),'awaiting_payment',(select count(*)from public.orders where status='awaiting_payment'),'paid_waiting',(select count(*)from public.orders where status='paid_awaiting_purchase'),'arrived_for_check',(select count(*)from public.orders where status='arrived_for_check'),'refund_pending',(select count(*)from public.orders where status='refund_pending'),'low_stock',(select count(*)from public.products p join public.inventory_balances b on b.product_id=p.id where p.publication_status<>'archived' and b.quantity_on_hand<=p.low_stock_threshold));
 return jsonb_build_object('from',p_from,'to',p_to,'timezone','Asia/Taipei','generated_at',now(),'summary',summary,'daily',daily,'channels',channels,'products',popular,'tasks',todo);
end $$;
revoke all on function private.business_report(date,date) from public,anon,authenticated;

create or replace function private.admin_business_query(p_action text,p_payload jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
declare config jsonb;old_value jsonb;ver timestamptz;channel text;rule jsonb;begin
 if auth.uid() is null or not private.is_store_admin() then raise insufficient_privilege using message='Administrator required';end if;
 if p_action='report' then return private.business_report((p_payload->>'from')::date,(p_payload->>'to')::date);
 elsif p_action='fee_quote' then return private.fee_quote(p_payload->>'channel',(p_payload->>'subtotal')::integer);
 elsif p_action='settings' then return jsonb_build_object('fee_rules',(select value from public.app_settings where key='fee_rules'),'fee_rules_updated_at',(select updated_at from public.app_settings where key='fee_rules'),'jobs',(select value from public.app_settings where key='jobs'));
 elsif p_action='save_fee_rule' then
  channel:=p_payload->>'channel';perform channel::public.sales_channel;
  perform pg_advisory_xact_lock(hashtextextended('wj_fee_rules',0));
  select value,updated_at into old_value,ver from public.app_settings where key='fee_rules' for update;
  if ver is distinct from (p_payload->>'expected_updated_at')::timestamptz then raise sqlstate 'PT409' using message='Fee rules changed on another device';end if;
  config:=coalesce(old_value,'{}');rule:=p_payload->'rule';
  if rule is null or rule='null'::jsonb then config:=config-channel;
  else
   if channel is null or rule->>'basis_points'is null or rule->>'fixed_twd'is null or rule->>'rounding'is null or (rule->>'basis_points')::integer not between 0 and 10000 or (rule->>'fixed_twd')::integer not between 0 and 2147483647 or rule->>'rounding' not in ('round','ceil','floor') or jsonb_typeof(rule->'enabled')is distinct from 'boolean' then raise check_violation using message='Invalid fee rule';end if;
   config:=jsonb_set(config,array[channel],jsonb_build_object('basis_points',(rule->>'basis_points')::int,'fixed_twd',(rule->>'fixed_twd')::int,'rounding',rule->>'rounding','enabled',(rule->>'enabled')::boolean));
  end if;
  insert into public.app_settings(key,value,updated_by)values('fee_rules',config,auth.uid())on conflict(key)do update set value=excluded.value,updated_by=excluded.updated_by,updated_at=clock_timestamp();
  insert into public.audit_logs(actor_user_id,entity_type,entity_id,action,before_data,after_data)values(auth.uid(),'settings','fee_rules','fee_rules_updated',old_value,config);return jsonb_build_object('saved',true);
 end if;raise invalid_parameter_value using message='Unsupported business query';
end $$;
create or replace function public.admin_business_query(p_action text,p_payload jsonb default '{}')returns jsonb language sql set search_path='' as $$select private.admin_business_query(p_action,p_payload);$$;
revoke all on function private.admin_business_query(text,jsonb),public.admin_business_query(text,jsonb) from public,anon;
grant execute on function private.admin_business_query(text,jsonb),public.admin_business_query(text,jsonb) to authenticated;
